#if DEBUG && targetEnvironment(simulator)
  import Foundation
  import XCTest
  @testable import CadenceLearner

  @MainActor
  final class ResearchUnifiedWordGoldenTests: XCTestCase {
    override func tearDown() {
      FeedbackProtocol.handler = nil
      super.tearDown()
    }

    func testActualClientAdultAndChildBytesMatchIndependentPythonProjectorGoldens() async throws {
      for (context, request, response) in [
        (
          ResearchPracticeContext.adult, UnifiedWordGolden.adultRequest,
          UnifiedWordGolden.adultResponse
        ),
        (.child(ageYears: 9), UnifiedWordGolden.child9Request, UnifiedWordGolden.child9Response),
      ] {
        let root = try JSONSerialization.jsonObject(with: Data(response.utf8)) as! [String: Any]
        let claims = try XCTUnwrap(root["claimLimits"] as? [String: Bool])
        XCTAssertEqual(Set(claims.keys), Set(FeedbackContract.claims))
        XCTAssertEqual(claims.count, 11)
        XCTAssertTrue(claims.values.allSatisfy { $0 == false })
        let result = try await execute(context: context, request: request, response: response)
        XCTAssertEqual(result.status, .observed)
        XCTAssertEqual(result.word, .modelMatched)
        XCTAssertFalse(result.pronunciationCorrectnessAssessed)
        XCTAssertFalse(result.diagnosisProvided)
      }
    }

    func testCrossContextGoldenResponseIsRejectedByActualClient() async throws {
      for (context, request, swappedResponse) in [
        (
          ResearchPracticeContext.adult, UnifiedWordGolden.adultRequest,
          UnifiedWordGolden.child9Response
        ),
        (.child(ageYears: 9), UnifiedWordGolden.child9Request, UnifiedWordGolden.adultResponse),
      ] {
        do {
          _ = try await execute(context: context, request: request, response: swappedResponse)
          XCTFail("Response from the other practice context was accepted")
        } catch {
          XCTAssertEqual(error as? RecordingFeedbackError, .invalidResponse)
        }
      }
    }

    private func execute(
      context: ResearchPracticeContext, request: String, response: String
    ) async throws -> RecordingFeedback {
      let file = FileManager.default.temporaryDirectory.appendingPathComponent(
        "unified-word-generated-" + UUID().uuidString + ".wav")
      try FeedbackFixture.wav().write(to: file)
      defer {
        try? FileManager.default.removeItem(at: file)
        FeedbackProtocol.handler = nil
      }
      let configuration = URLSessionConfiguration.ephemeral
      configuration.protocolClasses = [FeedbackProtocol.self]
      let expectedRequest = Data(request.utf8)
      let responseData = Data(response.utf8)
      FeedbackProtocol.handler = { actual in
        XCTAssertEqual(actual.url?.scheme, "http")
        XCTAssertEqual(actual.url?.host, "127.0.0.1")
        XCTAssertEqual(actual.url?.port, 8793)
        XCTAssertEqual(actual.value(forHTTPHeaderField: "Origin"), "http://127.0.0.1:8793")
        let body: Data
        if actual.url?.path == "/api/feedback-declaration" {
          XCTAssertEqual(actual.httpMethod, "GET")
          body = Data(UnifiedWordGolden.declaration.utf8)
        } else {
          XCTAssertEqual(actual.url?.path, "/api/feedback")
          XCTAssertEqual(actual.httpMethod, "POST")
          XCTAssertEqual(
            actual.value(forHTTPHeaderField: "X-Consumer-CSRF"), String(repeating: "f", count: 64))
          // Actual native client serialization must match separate Python bytes, without re-encoding.
          XCTAssertEqual(try FeedbackFixture.requestBody(actual), expectedRequest)
          body = responseData
        }
        return (
          HTTPURLResponse(
            url: actual.url!, statusCode: 200, httpVersion: nil,
            headerFields: ["Content-Type": "application/json"])!, body
        )
      }
      let bread = try XCTUnwrap(ResearchFeedbackCatalog.prompts.first { $0.id == "r-middle-bread" })
      return try await ResearchFeedbackClient(configuration: configuration).process(
        attemptId: UUID(uuidString: "00000000-0000-4000-8000-000000000123")!,
        recording: .init(url: file, summary: .init(duration: 0.2, averagePower: -12)),
        prompt: bread,
        practiceContext: context)
    }
  }

